func pick(name string) func(int) int {
    if name == "double" {
        return double
    }
    return triple
}

func main() {
    f := pick("double")
    g := pick("triple")
    fmt.Println(f(7), g(7))
}

func inc(n int) int {
    return n + 1
}

func square(n int) int {
    return n * n
}

func main() {
    steps := []func(int) int{inc, square}
    for _, step := range steps {
        fmt.Println(step(6))
    }
}

